WITH targets AS (
 SELECT c.*, (SELECT json_group_array(value) FROM (SELECT DISTINCT CAST(j.value AS INTEGER) AS value FROM clientDossiers d,json_each(d.data,'$.requiredYears') j WHERE d.clientId=c.id AND j.type='integer' AND j.value BETWEEN 1900 AND 2100 ORDER BY value)) AS targetYears,
 COALESCE((SELECT json_extract(p.data,'$.taxCardExpires') FROM clientProfiles p WHERE p.clientId=c.id),'') AS cardExpiry
 FROM clients c WHERE c.taxOffice='تالت و رابع' AND NOT EXISTS(SELECT 1 FROM inspectionCases i WHERE i.clientId=c.id AND i.taxType='دخل')
)
INSERT INTO inspectionCases (id,clientId,taxType,periodKey,staffId,reviewerId,approverId,updateStaffId,sourceKey,data,revision,created,updated)
SELECT id,id,'دخل',COALESCE((SELECT group_concat(value,',') FROM json_each(targetYears)),'غير محدد'),NULL,(SELECT id FROM staff WHERE code='2' AND (SELECT count(*) FROM staff WHERE code='2')=1),(SELECT id FROM staff WHERE code='1' AND (SELECT count(*) FROM staff WHERE code='1')=1),(SELECT id FROM staff WHERE code='5' AND (SELECT count(*) FROM staff WHERE code='5')=1),'third-fourth-plan:'||id,
json_set('{"title":"خطة فحص ضريبي","taxType":"دخل","years":[],"office":"تالت و رابع","division":"","examiner":"","staffId":null,"reviewerId":null,"approverId":null,"updateStaffId":null,"stage":"استعلام","priority":"عادية","nextAction":"استعلام موقف العميل بالمأمورية وتحديد المأمور وسنوات الفحص المفتوحة وحصر المستندات الناقصة.","nextDue":"","blockers":"","cardStatus":"يلزم مراجعة سريان البطاقة الضريبية","cardExpiry":"","updateStatus":"مراجعة بيانات التواصل والمقر والتوكيل والتسجيل بالمنظومات","review":"مسودة","result":"","closedDate":"","completedYears":[],"settledYears":[],"assessed":0,"taxPaid":0,"documents":[],"notes":"١. استعلام الموقف وتحديد المأمور وسنوات الفحص المفتوحة.\n٢. مراجعة التوكيل والهوية والبطاقة وشهادات النظام الضريبي وتحديث البيانات.\n٣. حصر الإقرارات وإشعارات الخصم والإيرادات والمصروفات عن السنوات المحددة.\n٤. إعداد المطابقات وحوافظ المستندات والمذكرات وعرضها للمراجعة الفنية.\n٥. تسجيل الجلسات والإخطارات وإثبات الاستلام والمواعيد التي راجعها المكتب.\n٦. توثيق نتيجة الفحص والتسوية، وتحديد السنوات المنتهية وتحديث موقف العميل.","sourceNote":"خطة أولية بطلب صاحب المكتب لكل عملاء تالت و رابع. السنوات من موقف العميل المسجل عند وجودها، وبخلاف ذلك تحتاج استعلامًا.","sessions":[],"deadlines":[]}','$.title',substr('خطة فحص تالت و رابع — '||name,1,200),'$.years',json(targetYears),'$.reviewerId',(SELECT id FROM staff WHERE code='2' AND (SELECT count(*) FROM staff WHERE code='2')=1),'$.approverId',(SELECT id FROM staff WHERE code='1' AND (SELECT count(*) FROM staff WHERE code='1')=1),'$.updateStaffId',(SELECT id FROM staff WHERE code='5' AND (SELECT count(*) FROM staff WHERE code='5')=1),'$.cardExpiry',cardExpiry),1,strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM targets WHERE 1=1
ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO inspectionHistory (id,caseId,revision,data,actor,created)
SELECT id,id,revision,data,'إنشاء خطة تالت و رابع بطلب صاحب المكتب',created FROM inspectionCases c WHERE sourceKey LIKE 'third-fourth-plan:%' AND NOT EXISTS(SELECT 1 FROM inspectionHistory h WHERE h.caseId=c.id AND h.revision=c.revision);
--> statement-breakpoint
INSERT INTO securityLog (id,actor,action,created) VALUES ('third-fourth-inspection-plan-0014','صاحب المكتب — طلب إعداد الخطة','إنشاء خطط فحص دخل مبدئية لجميع عملاء تالت و رابع مع الاحتفاظ بالخطط السابقة',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
